const raw = $json.output?.[0]?.content?.[0]?.text;

if (!raw) {
  throw new Error('AI invoice extraction returned no text.');
}

let invoice;

try {
  invoice = JSON.parse(raw);
} catch (error) {
  throw new Error(`AI returned invalid JSON: ${error.message}`);
}

const requiredFields = [
  'supplier_name',
  'invoice_number',
  'invoice_date',
  'currency',
  'total',
  'items'
];

for (const field of requiredFields) {
  if (invoice[field] === undefined || invoice[field] === null) {
    throw new Error(`Required invoice field is missing: ${field}`);
  }
}

if (!Array.isArray(invoice.items) || invoice.items.length === 0) {
  throw new Error('Invoice contains no valid line items.');
}

return {
  json: invoice
};

