const invoice = $('Code - Parse Invoice JSON').first().json;
const createdInvoice = $input.first().json;

if (!createdInvoice.invoice_id) {
  throw new Error('Created invoice ID is missing.');
}

if (!createdInvoice.organization_id) {
  throw new Error('Organization ID is missing.');
}

if (!createdInvoice.supplier_id) {
  throw new Error('Supplier ID is missing.');
}

if (!Array.isArray(invoice.items) || invoice.items.length === 0) {
  throw new Error('Invoice contains no line items.');
}

return invoice.items.map((item, index) => ({
  json: {
    invoice_id: createdInvoice.invoice_id,

    invoice_line_number: index + 1,

    organization_id: createdInvoice.organization_id,
    supplier_id: createdInvoice.supplier_id,
    purchase_order_id: createdInvoice.purchase_order_id,

    supplier_name: invoice.supplier_name,
    supplier_code: invoice.supplier_code,

    invoice_number: invoice.invoice_number,
    invoice_date: invoice.invoice_date,

    po_number: invoice.po_number,
    currency: invoice.currency,

    description: item.description,
    supplier_sku: item.supplier_sku,

    quantity: Number(item.quantity),
    unit_price: Number(item.unit_price),
    line_total: Number(item.line_total)
  }
}));

const candidates = $input.all().map(item => item.json);

function normalize(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/litre/g, 'liter')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokens(value) {
  return normalize(value)
    .split(' ')
    .filter(word => word.length > 1);
}

function similarity(a, b) {
  const aTokens = new Set(tokens(a));
  const bTokens = new Set(tokens(b));

  if (aTokens.size === 0 || bTokens.size === 0) {
    return 0;
  }

  let matches = 0;

  for (const word of aTokens) {
    if (bTokens.has(word)) {
      matches++;
    }
  }

  return matches / Math.max(aTokens.size, bTokens.size);
}

const grouped = {};

for (const row of candidates) {
  const line = Number(row.invoice_line_number);

  if (!grouped[line]) {
    grouped[line] = [];
  }

  const invoiceSku = normalize(row.invoice_supplier_sku);
  const mappedSku = normalize(row.mapped_supplier_sku);
  const internalSku = normalize(row.internal_sku);

  const productNameSimilarity = similarity(
    row.invoice_description,
    row.internal_product_name
  );

  const poDescriptionSimilarity = similarity(
    row.invoice_description,
    row.description_from_po
  );

  const aliasSimilarity = similarity(
    row.invoice_description,
    row.alias_name
  );

  let score = 0;
  const reasons = [];

  // Strongest evidence: exact supplier SKU
  if (invoiceSku && mappedSku && invoiceSku === mappedSku) {
    score += 60;
    reasons.push('exact_supplier_sku');
  }

  // Exact internal SKU
  if (invoiceSku && internalSku && invoiceSku === internalSku) {
    score += 50;
    reasons.push('exact_internal_sku');
  }

  // Product name similarity
  if (productNameSimilarity >= 0.8) {
    score += 35;
    reasons.push('strong_product_name');
  } else if (productNameSimilarity >= 0.5) {
    score += 20;
    reasons.push('partial_product_name');
  }

  // PO description similarity
  if (poDescriptionSimilarity >= 0.8) {
    score += 30;
    reasons.push('strong_po_description');
  } else if (poDescriptionSimilarity >= 0.5) {
    score += 15;
    reasons.push('partial_po_description');
  }

  // Human-verified alias similarity
  if (aliasSimilarity >= 0.8) {
    score += 35;
    reasons.push('strong_verified_alias');
  } else if (aliasSimilarity >= 0.5) {
    score += 20;
    reasons.push('partial_verified_alias');
  }

  // Quantity is only supporting evidence
  const invoiceQty = Number(row.invoice_quantity);
  const orderedQty = Number(row.ordered_quantity);

  if (
    Number.isFinite(invoiceQty) &&
    Number.isFinite(orderedQty) &&
    invoiceQty === orderedQty
  ) {
    score += 10;
    reasons.push('quantity_matches_po');
  }

  grouped[line].push({
    ...row,

    product_name_similarity:
      Number(productNameSimilarity.toFixed(3)),

    po_description_similarity:
      Number(poDescriptionSimilarity.toFixed(3)),

    alias_similarity:
      Number(aliasSimilarity.toFixed(3)),

    match_score: score,
    match_reasons: reasons
  });
}

const results = [];

for (const line of Object.keys(grouped)) {
  const lineCandidates = grouped[line];

  lineCandidates.sort(
    (a, b) => b.match_score - a.match_score
  );

  const best = lineCandidates[0];
  const second = lineCandidates[1];

  const scoreGap = second
    ? best.match_score - second.match_score
    : best.match_score;

  let matchStatus = 'UNMATCHED';

  if (best.match_score >= 60 && scoreGap >= 15) {
    matchStatus = 'MATCHED';
  } else if (best.match_score >= 35 && scoreGap >= 10) {
    matchStatus = 'REVIEW';
  }

  results.push({
    json: {
      ...best,

      second_best_score:
        second ? second.match_score : null,

      score_gap: scoreGap,
      match_status: matchStatus,
      candidate_count: lineCandidates.length
    }
  });
}

return results;

const row = $json;

let classification;
let anomalyType = null;
let requiresReview = false;

// Recover the scored candidate belonging to this exact invoice line.
const scoredItems = $('Code - Score Product Candidates').all();

const scored = scoredItems.find(
  item =>
    Number(item.json.invoice_line_number) ===
    Number(row.invoice_line_number)
);

const candidate = scored?.json ?? null;

const score = Number(candidate?.match_score ?? 0);

if (row.catalog_product_found === true) {
  classification = 'KNOWN_CATALOG_PRODUCT';
} else if (score >= 25) {
  classification = 'POSSIBLE_PRODUCT_MATCH';
  requiresReview = true;
} else {
  classification = 'UNKNOWN_PRODUCT';
  anomalyType = 'UNKNOWN_PRODUCT';
}

return {
  ...row,

  best_candidate_product_id:
    candidate?.product_id ?? null,

  best_candidate_sku:
    candidate?.internal_sku ?? null,

  best_candidate_name:
    candidate?.internal_product_name ?? null,

  best_candidate_po_item_id:
    candidate?.po_item_id ?? null,

  best_candidate_score:
    score,

  best_candidate_score_gap:
    candidate?.score_gap ?? null,

  best_candidate_reasons:
    candidate?.match_reasons ?? [],

  best_candidate_alias_similarity:
    candidate?.alias_similarity ?? null,

  best_candidate_product_name_similarity:
    candidate?.product_name_similarity ?? null,

  best_candidate_po_description_similarity:
    candidate?.po_description_similarity ?? null,

  classification,
  anomaly_type: anomalyType,
  requires_review: requiresReview
};

const persistedItems = $input.all();

const createdInvoice = $('DB - Create Invoice').first().json;
const supplier = $('DB - Match Supplier').first().json;

return persistedItems.map(item => {
  const row = item.json;

  return {
    json: {
      invoice_item_id: row.invoice_item_id,
      invoice_id: row.invoice_id,

      invoice_line_number: Number(row.invoice_line_number),

      organization_id: row.organization_id,
      supplier_id: supplier.id,
      purchase_order_id: createdInvoice.purchase_order_id,

      invoice_number: createdInvoice.invoice_number,
      invoice_date: createdInvoice.invoice_date,
      currency: createdInvoice.currency,

      invoice_supplier_sku: row.supplier_sku,
      invoice_description: row.description,

      invoice_quantity: Number(row.quantity),
      invoice_unit_price: Number(row.unit_price),
      invoice_line_total: Number(row.line_total),

      product_id: row.product_id,
      purchase_order_item_id: row.purchase_order_item_id
    }
  };
});

const persisted = $json;

const matched =
  $("Code - Score Product Candidates").item.json;

// --------------------------------------------------
// Convert required values to numbers
// --------------------------------------------------

const invoiceQty =
  Number(matched.invoice_quantity || 0);

const invoiceUnitPrice =
  Number(matched.invoice_unit_price || 0);

const poQty =
  Number(matched.ordered_quantity || 0);

const poUnitPrice =
  Number(
    matched.agreed_unit_price ||
    matched.po_unit_price ||
    0
  );

const tolerancePercent =
  Number(matched.tolerance_percent || 0);

// --------------------------------------------------
// PRICE VARIANCE
// --------------------------------------------------

const priceVarianceAmount =
  invoiceUnitPrice - poUnitPrice;

const priceVariancePercent =
  poUnitPrice > 0
    ? (priceVarianceAmount / poUnitPrice) * 100
    : 0;

const priceOutsideTolerance =
  poUnitPrice > 0 &&
  priceVariancePercent > tolerancePercent;

const estimatedPriceImpact =
  priceOutsideTolerance
    ? priceVarianceAmount * invoiceQty
    : 0;

// --------------------------------------------------
// QUANTITY VARIANCE
// --------------------------------------------------

const quantityVariance =
  invoiceQty - poQty;

const quantityVariancePercent =
  poQty > 0
    ? (quantityVariance / poQty) * 100
    : 0;

const quantityOutsideTolerance =
  poQty > 0 &&
  quantityVariancePercent > tolerancePercent;

// --------------------------------------------------
// Return normalized matched-item result
// --------------------------------------------------

return {
  json: {
    organization_id: persisted.organization_id,
    invoice_id: persisted.invoice_id,
    invoice_item_id: persisted.invoice_item_id,
    product_id: persisted.product_id,
    purchase_order_item_id:
      persisted.purchase_order_item_id,

    supplier_id: matched.supplier_id,
    purchase_order_id:
      matched.purchase_order_id,

    invoice_description:
      matched.invoice_description,

    invoice_quantity: invoiceQty,
    ordered_quantity: poQty,

    invoice_unit_price: invoiceUnitPrice,
    expected_unit_price: poUnitPrice,

    tolerance_percent: tolerancePercent,

    price_variance_amount:
      priceVarianceAmount,

    price_variance_percent:
      priceVariancePercent,

    price_outside_tolerance:
      priceOutsideTolerance,

    estimated_price_impact:
      estimatedPriceImpact,

    quantity_variance:
      quantityVariance,

    quantity_variance_percent:
      quantityVariancePercent,

    quantity_outside_tolerance:
      quantityOutsideTolerance
  }
};

